'use client';

/**
 * <StartLightsLoader>
 *
 * An authentic Formula 1 race start loader.
 *
 * Sequence:
 *   1. Intro Phase   — Elegant F1PULSE logo on black screen.
 *   2. Reveal Phase  — Renders the current/next circuit outline using clean SVG paths.
 *                      A telemetry sweep runs along the outline if data is loading.
 *   3. Lights Phase  — Five red start lights illuminate one-by-one with authentic FIA gantry beeps (600ms).
 *                      The track progressively glows red in sync with the lights.
 *   4. Hold Phase    — Tension hold: all lights illuminated, silence, anticipation.
 *   5. Wipe Phase    — LIGHTS OUT! All red lights vanish instantly. Start is silent (motors roar).
 *                      The shutter rolls up like a pit garage door, revealing the hero.
 *
 * Returns a premium, motorsport-authentic opening sequence.
 */

import { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { useReducedMotion } from '@/hooks/useReducedMotion';
import { playLightBeep, stopLightBeep } from '@/lib/audio';
import type { RaceScheduleDto } from '@/lib/api';

