export interface StartLightsLoaderProps {
  ready: boolean;
  onRevealStart: () => void;
  onComplete: () => void;
  nextRace?: RaceScheduleDto | null;
}

export function StartLightsLoader({
  ready,
  onRevealStart,
  onComplete,
  nextRace,
}: StartLightsLoaderProps) {
  const reduced = useReducedMotion();
  const [currentLight, setCurrentLight] = useState(0);
  const [phase, setPhase] = useState<
    'intro-fade-in' | 'intro-hold' | 'intro-fade-out' | 'breathing' | 'countdown' | 'hold' | 'out' | 'done'
  >('intro-fade-in');
  const [breathingElapsed, setBreathingElapsed] = useState(false);

  const circuitId = nextRace?.circuit?.id || 'default';
  const circuitInfo = CIRCUIT_MAPS[circuitId] || CIRCUIT_MAPS['default'];

  // Unlocking AudioContext on screen click
  const handleScreenClick = () => {
    setPhase((prev) => {
      if (prev === 'intro-fade-in' || prev === 'intro-hold') {
        playLightBeep(1, true);
        return 'intro-fade-out';
      }
      return prev;
    });
  };

  useEffect(() => {
    // Attempt auto-resuming Web Audio
    playLightBeep(1, true);

    const unlock = () => {
      playLightBeep(1, true); // Silent sample play in user gesture call stack
      setPhase((prev) => {
        if (prev === 'intro-fade-in' || prev === 'intro-hold') {
          return 'intro-fade-out';
        }
        return prev;
      });
      window.removeEventListener('click', unlock);
      window.removeEventListener('touchstart', unlock);
    };
    window.addEventListener('click', unlock);
    window.addEventListener('touchstart', unlock);

    return () => {
      window.removeEventListener('click', unlock);
      window.removeEventListener('touchstart', unlock);
      stopLightBeep();
    };
  }, []);

  // Automatically transition from fade-in to hold phase after 1s
  useEffect(() => {
    if (phase !== 'intro-fade-in') return;
    const timer = setTimeout(() => {
      setPhase('intro-hold');
    }, 1000);
    return () => clearTimeout(timer);
  }, [phase]);

  // Optional hold phase automatic timeout: transition to fade-out after 450ms if not clicked
  useEffect(() => {
    if (phase !== 'intro-hold') return;
    const timer = setTimeout(() => {
      setPhase('intro-fade-out');
    }, 450);
    return () => clearTimeout(timer);
  }, [phase]);

  // Breathing space timer (350ms duration)
  useEffect(() => {
    if (phase !== 'breathing') {
      setBreathingElapsed(false);
      return;
    }
    const timer = setTimeout(() => {
      setBreathingElapsed(true);
    }, 350);
    return () => clearTimeout(timer);
  }, [phase]);

  // Transition to countdown phase only when breathing has elapsed AND track map data is ready
  useEffect(() => {
    if (phase === 'breathing' && breathingElapsed && ready) {
      setPhase('countdown');
    }
  }, [phase, breathingElapsed, ready]);

  // Countdown timer sequence aligned with beep.mp3 peak timestamps
  useEffect(() => {
    if (phase !== 'countdown') return;

    const timers: number[] = [];

    // 0ms: Kick off full sequence audio if present
    playLightBeep(0);

    // Light 1 ON at 930ms
    timers.push(
      window.setTimeout(() => {
        setCurrentLight(1);
        playLightBeep(1);
      }, 930)
    );

    // Light 2 ON at 1940ms
    timers.push(
      window.setTimeout(() => {
        setCurrentLight(2);
        playLightBeep(2);
      }, 1940)
    );

    // Light 3 ON at 2940ms
    timers.push(
      window.setTimeout(() => {
        setCurrentLight(3);
        playLightBeep(3);
      }, 2940)
    );

    // Light 4 ON at 3940ms
    timers.push(
      window.setTimeout(() => {
        setCurrentLight(4);
        playLightBeep(4);
      }, 3940)
    );

    // Light 5 ON at 4940ms -> transition to hold phase (audio continues playing)
    timers.push(
      window.setTimeout(() => {
        setCurrentLight(5);
        playLightBeep(5);
        setPhase('hold');
      }, 4940)
    );

    return () => {
      timers.forEach((t) => window.clearTimeout(t));
    };
  }, [phase]);

  // Handle the lights out transition once all lights are on AND page is ready
  useEffect(() => {
    if (phase !== 'hold' || !ready) return;

    // tension hold before lights out: exactly 2000ms
    const timer = setTimeout(() => {
      stopLightBeep();
      setPhase('out');
      onRevealStart();
      setPhase('done');
      onComplete();
    }, 2000);

    return () => clearTimeout(timer);
  }, [phase, ready, onRevealStart, onComplete]);

  // If the user has reduced motion enabled, just complete immediately once ready
  useEffect(() => {
    if (reduced && ready) {
      stopLightBeep();
      onRevealStart();
      onComplete();
    }
  }, [reduced, ready, onRevealStart, onComplete]);

  if (phase === 'done') return null;

  const pods = Array.from({ length: 5 });
  const extinguishing = phase === 'out';
  const wiping = phase === 'out';

  return (
    <div
      role="status"
      aria-live="polite"
      aria-busy={true}
      className="fixed inset-0 z-[9000] flex flex-col items-center justify-center bg-transparent pointer-events-none"
    >
      {/* ── Editorial Slats Shutter Background ─────────────────────────────── */}
      <div 
        className="absolute inset-0 flex pointer-events-auto overflow-hidden z-0 cursor-pointer"
        onClick={handleScreenClick}
      >
        {/* Slat 1: Slides UP instantly (duration 0) */}
        <motion.div
          className="h-full bg-[#0c0c0d] border-r border-white/[0.04]"
          style={{ width: '33.333%' }}
          initial={{ y: '0%' }}
          animate={{ y: wiping ? '-100%' : '0%' }}
          transition={{ duration: 0 }}
        />
        {/* Slat 2: Slides DOWN instantly (duration 0) */}
        <motion.div
          className="h-full bg-[#0c0c0d] border-r border-white/[0.04]"
          style={{ width: '33.333%' }}
          initial={{ y: '0%' }}
          animate={{ y: wiping ? '100%' : '0%' }}
          transition={{ duration: 0 }}
        />
        {/* Slat 3: Slides UP instantly (duration 0) */}
        <motion.div
          className="h-full bg-[#0c0c0d]"
          style={{ width: '33.334%' }}
          initial={{ y: '0%' }}
          animate={{ y: wiping ? '-100%' : '0%' }}
          transition={{ duration: 0 }}
        />
      </div>

      {/* ── Centered Content (Gantry + Text + Track) ───────────────────────── */}
      <motion.div
        className="z-10 flex flex-col items-center justify-center gap-6 select-none text-center"
        initial={{ opacity: 1, scale: 1 }}
        animate={{
          opacity: wiping ? 0 : 1,
          scale: wiping ? 0.95 : 1,
        }}
        transition={{ duration: 0 }}
      >
        {/* F1 Circuit Layout - Always visible from the start */}
        {circuitInfo && (
          <div className="relative w-64 h-48 flex items-center justify-center mx-auto">
            <svg
              viewBox={circuitInfo.viewBox}
              className="w-full h-full text-steel/20 stroke-current fill-none stroke-[2.5]"
              style={{ strokeLinecap: 'round', strokeLinejoin: 'round' }}
            >
              {/* Dim base outline */}
              <path d={circuitInfo.path} className="opacity-30" />
              
              {/* Progressive track glow overlay based on lit gantry lights */}
              {(phase === 'countdown' || phase === 'hold' || phase === 'out') && (
                <motion.path
                  d={circuitInfo.path}
                  className="stroke-accent drop-shadow-[0_0_8px_rgba(255,24,35,0.7)]"
                  initial={{ pathLength: 0 }}
                  animate={{ pathLength: phase === 'hold' ? 1 : currentLight / 5 }}
                  transition={{ duration: 0.8, ease: 'easeOut' }}
                />
              )}
            </svg>
          </div>
        )}

        {/* Intro Phase Text: SOUND RECOMMENDED / CLICK ANYWHERE FOR AUDIO */}
        {(phase === 'intro-fade-in' || phase === 'intro-hold' || phase === 'intro-fade-out') && (
          <motion.div
            key="intro-text"
            initial={{ opacity: 0, y: 8 }}
            animate={{ 
              opacity: phase === 'intro-fade-out' ? 0 : 1,
              y: phase === 'intro-fade-out' ? -8 : 0
            }}
            transition={{ duration: 0.8, ease: 'easeInOut' }}
            onAnimationComplete={() => {
              if (phase === 'intro-fade-out') {
                setPhase('breathing');
              }
            }}
            className="flex flex-col items-center justify-center gap-3 mt-4"
          >
            <span className="font-serif italic text-lg sm:text-xl text-[#eeeeee] tracking-wider">
              SOUND RECOMMENDED
            </span>
            <span className="font-mono text-[0.65rem] sm:text-xs uppercase tracking-[0.4em] text-white/50 font-semibold">
              CLICK ANYWHERE FOR AUDIO
            </span>
          </motion.div>
        )}

        {/* Gantry & Loader Details Phase Content */}
        {(phase === 'countdown' || phase === 'hold' || phase === 'out') && (
          <motion.div
            key="gantry-content"
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="flex flex-col items-center justify-center gap-6"
          >
            {/* Start Lights Gantry */}
            <div className="flex flex-col items-center gap-3">
              <div className="flex items-center gap-4 bg-white/[0.02] p-3 rounded-xl border border-white/[0.05] backdrop-blur-sm">
                {pods.map((_, idx) => {
                  const isLit = currentLight > idx && !extinguishing;
                  return (
                    <div
                      key={idx}
                      className="relative h-10 w-10 rounded-full border-2 border-white/[0.1] flex items-center justify-center bg-black sm:h-14 sm:w-14"
                    >
                      {isLit && (
                        <motion.span
                          className="h-6 w-6 rounded-full bg-accent sm:h-9 sm:w-9 drop-shadow-[0_0_12px_rgba(255,24,35,0.85)]"
                          initial={{ scale: 0.8, opacity: 0 }}
                          animate={{ scale: 1, opacity: 1 }}
                          transition={{ type: 'spring', stiffness: 200, damping: 15 }}
                        />
                      )}
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Editorial loader details */}
            <div className="flex flex-col items-center gap-2 mt-4 text-center">
              <span className="font-serif italic text-sm text-silver">
                {phase === 'hold' ? 'PREPARE FOR START' : 'CONNECTING TELEMETRY'}
              </span>
              <span className="font-mono text-[0.65rem] uppercase tracking-[0.35em] text-white font-semibold">
                F1Pulse // Vol. I
              </span>
            </div>
          </motion.div>
        )}
      </motion.div>

      <span className="sr-only">
        Loading season data
      </span>
    </div>
  );
}
